def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]

    row_lines = [r for r in range(h)
                 if len(set(grid[r])) == 1 and grid[r][0] != bg]
    col_lines = [c for c in range(w)
                 if len({grid[r][c] for r in range(h)}) == 1
                 and grid[0][c] != bg]

    if len(row_lines) >= 2 or (row_lines and not col_lines):
        axis, lines, n = 0, row_lines, h
    elif col_lines:
        axis, lines, n = 1, col_lines, w
    else:
        return [row[:] for row in grid]

    if len(lines) >= 2:
        period = lines[1] - lines[0]
        for a, b in zip(lines[1:], lines[2:]):
            import math
            period = math.gcd(period, b - a)
    else:
        period = lines[0] + 1
    if period <= 0:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    if axis == 0:
        for r in range(h):
            for c in range(w):
                if out[r][c] == bg:
                    vals = [grid[q][c] for q in range(h)
                            if q % period == r % period and grid[q][c] != bg]
                    if vals:
                        out[r][c] = Counter(vals).most_common(1)[0][0]
    else:
        for r in range(h):
            for c in range(w):
                if out[r][c] == bg:
                    vals = [grid[r][q] for q in range(w)
                            if q % period == c % period and grid[r][q] != bg]
                    if vals:
                        out[r][c] = Counter(vals).most_common(1)[0][0]
    return out
